#include <stdio.h>
#include <stdlib.h>

/**
 * 下面时基于单向链表实现的队列，入队enqueue，出队dequeue
 */
typedef int bool;
#define TRUE 1
#define FALSE 0

// 队列元素类型（初始默认为int，后期可以改为需要的类型）
typedef int E;

// 单向链表节点结构体
typedef struct ListNode {
    E ele; // 节点值
    struct ListNode *next; // 后继节点
} Node;

// 链表结构体
typedef struct LinkedList {
    Node *head; // 头节点
    Node *tail; // 尾节点
    int size; // 队列长度
} Queue; // 使用链表模拟队列

/*!
 * 初始化队列
 * @return 队列指针
 */
Queue *init() {
    // 申请内存
    Queue *queue = (Queue *) malloc(sizeof(Queue));

    // 申请内存失败
    if (queue == NULL) {
        return NULL;
    }

    // 初始化队列成员
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;

    return queue;
}

/*!
 * 释放队列
 * @param queue 队列
 */
void destroy(Queue* queue) {
    Node* cur = queue->head;

    // 释放队列各个节点的内存
    while(cur != NULL) {
        Node* tmp = cur->next;
        free(cur);
        cur = tmp;
    }

    // 释放队列结构体内存
    free(queue);
}

/*!
 * 入队
 * @param queue 队列
 * @param ele 入队元素
 * @return 操作结果
 */
bool enqueue(Queue* queue, E ele) {
    // 申请内存，创建一个新节点
    Node *node = (Node *) malloc(sizeof(Node));

    // 申请内存失败
    if (node == NULL) {
        return FALSE;
    }

    // 初始化节点
    node->ele = ele;
    node->next = NULL;

    if (queue->size == 0) {
        // 空队列插入
        queue->head = node;
        queue->tail = node;
    } else {
        // 尾插
        queue->tail->next = node;
        queue->tail = node;
    }

    // 节点数+1
    queue->size++;

    return TRUE;
}

/*!
 * 出队
 * @param queue 队列
 * @return 出队元素的地址（注意：返回值特地申请了一块内存来存储，因此使用完后，需要释放返回值占用的内存）
 */
E* dequeue(Queue* queue) {
    // 空队列无法出队
    if(queue->size == 0) {
        return NULL;
    }

    // 指向将被删除节点
    Node *removeNode;

    if (queue->size == 1) {
        // 单节点队列删除唯一节点
        removeNode = queue->head;
        queue->head = NULL;
        queue->tail = NULL;
    } else {
        // 头删
        removeNode = queue->head;
        queue->head = queue->head->next;
    }

    // 队列节点个数-1
    queue->size--;

    // 申请一块内存用于存放被删除节点的值
    E *p = (E *) malloc(sizeof(E));
    *p = removeNode->ele;

    // 释放被删除节点的空间
    free(removeNode);

    return p;
}


