#define MAX_ROWS 100
#define MAX_COLS 100

int m, n;
int matrix[MAX_ROWS][MAX_COLS];

int getResult();

int main() {
    scanf("%d %d", &m, &n);

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    matrix[0][0] = 1;

    printf("%d\n", getResult());

    return 0;
}

int getResult() {
    int offsets[4][2] = {{-1, 0},
                         {1,  0},
                         {0,  1},
                         {0,  -1}};

    Queue *queue = init();

    enqueue(queue, 0 * n + 0);
    int count = 1;

    while (queue->size > 0) {
        int* pos = dequeue(queue);

        int x = *pos / n;
        int y = *pos % n;

        // dequeue返回值是存放在一块专门申请的内存中的，因此需要释放
        free(pos);

        for (int i = 0; i < 4; i++) {
            int newX = x + offsets[i][0];
            int newY = y + offsets[i][1];

            if (newX >= 0 && newX < m && newY >= 0 && newY < n && matrix[newX][newY] == 0) {
                matrix[newX][newY] = 1;
                count++;
                enqueue(queue, newX * n + newY);
            }
        }
    }

    // 释放链表内存
    destroy(queue);

    return m * n - count;
}
